package com.thurdass.system2a.dto.response; import com.thurdass.system2a.entity.Announcement; import java.time.*; public record AnnouncementResponse(Long id,String title,String content,LocalDateTime createdAt,String createdBy,boolean pinned){public static AnnouncementResponse of(Announcement a){return new AnnouncementResponse(a.getId(),a.getTitle(),a.getContent(),a.getCreatedAt(),a.getCreatedBy().getUsername(),a.isPinned());}}
